using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
public static class VerifySceneAttackSettingsCache {
 delegate bool Lookup(DirectedWaveAttackBehaviour b,int s,bool e,out DirectedWaveAttackSettings v,out int i);
 static Type Cache=>typeof(DirectedWaveAttackBehaviourEditor).Assembly.GetType("SceneAttackSettingsCache");
 static Lookup Get=(Lookup)Cache.GetMethod("TryGet",BindingFlags.Static|BindingFlags.NonPublic).CreateDelegate(typeof(Lookup));
 static Action Clear=(Action)Cache.GetMethod("Clear",BindingFlags.Static|BindingFlags.NonPublic).CreateDelegate(typeof(Action));
 static List<string> checks=new();
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks.Add(name);}
 static DirectedWaveAttackSettings Read(DirectedWaveAttackBehaviour b,int slot=0,bool entrance=false){Check(Get(b,slot,entrance,out var v,out _),"resolve "+slot+" "+entrance);return v;}
 static void Patch(DirectedWaveAttackBehaviour b,string json){JsonUtility.FromJsonOverwrite(json,b);EditorUtility.SetDirty(b);b.InvalidateSequenceGuides();}
 static void Set(Object o,string path,object value){using var so=new SerializedObject(o);var p=so.FindProperty(path);if(value is bool flag)p.boolValue=flag;else if(value is float f)p.floatValue=f;else if(value is int i)p.intValue=i;else p.objectReferenceValue=(Object)value;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(o);}
 static void Eq(DirectedWaveAttackBehaviour b,int slot,bool entrance=false){bool ok=Get(b,slot,entrance,out var actual,out int ai);var expected=new DirectedWaveAttackSettings();bool eo=b.TryCopyResolvedAttackSettingsTo(slot,entrance,expected,out int ei);Check(ok==eo&&ai==ei,"eligibility/index "+slot+" "+entrance);if(ok){Check(JsonUtility.ToJson(actual)==JsonUtility.ToJson(expected),"serialized equality "+slot+" "+entrance);Check(actual.RuntimeAttackSpeedMultiplier==expected.RuntimeAttackSpeedMultiplier&&actual.RuntimeProjectileBaseSpeedOverride==expected.RuntimeProjectileBaseSpeedOverride,"runtime overrides "+slot);}}
 public static object Run(){checks.Clear();Clear();var objects=new List<Object>();int undoGroup=-1;GameObject fixtureRoot=null;
 try {
  fixtureRoot=PrefabUtility.LoadPrefabContents("Assets/Waves/2/2_5_extrime.prefab");foreach(int id in new[]{3,4,5}){var go=fixtureRoot.GetComponentsInChildren<Transform>(true).First(t=>t.name=="SubWave_1 ("+id+")");var b=go.GetComponent<DirectedWaveAttackBehaviour>();var w=go.GetComponent<DirectedEnemySubWave>();for(int slot=0;slot<w.GetConfiguredEnemySlotCount();slot++)Eq(b,slot);}
  var root=new GameObject("Scene cache regression (temporary)"){hideFlags=HideFlags.HideAndDontSave};objects.Add(root);var fixture=root.AddComponent<DirectedWaveAttackBehaviour>();
  Patch(fixture,"{\"attackSettings\":{\"attacksPerSecond\":2}}");var first=Read(fixture);Check(ReferenceEquals(first,Read(fixture,1)),"Single shares immutable settings across slots");
  using(var so=new SerializedObject(fixture)){so.FindProperty("attackSettings.attacksPerSecond").floatValue=7;so.ApplyModifiedPropertiesWithoutUndo();}EditorUtility.SetDirty(fixture);
  var changed=Read(fixture);Check(changed.AttacksPerSecond==7&&!ReferenceEquals(first,changed),"serialized edit invalidates immediately");
  Undo.IncrementCurrentGroup();undoGroup=Undo.GetCurrentGroup();Undo.RegisterCompleteObjectUndo(fixture,"Scene cache test");Set(fixture,"attackSettings.attacksPerSecond",8f);Undo.FlushUndoRecordObjects();Check(Read(fixture).AttacksPerSecond==8,"value before Undo");Undo.PerformUndo();Check(Read(fixture).AttacksPerSecond==7,"Undo invalidates");Undo.PerformRedo();Check(Read(fixture).AttacksPerSecond==8,"Redo invalidates");
  Patch(fixture,"{\"useSelectedEnemySlots\":true,\"selectedEnemySlots\":[1]}");Check(!Get(fixture,0,false,out _,out _),"Single excluded slot: selected="+fixture.UsesSelectedEnemySlots+" allowed="+fixture.AllowsSequenceSlot(0)+" patterns="+fixture.AttackPatternCount+" sequence="+fixture.UsesAttackSequence);Eq(fixture,1);Check(!Get(fixture,1,true,out _,out _),"disabled entrance");Set(fixture,"entranceAttackSettings.isEnabled",true);var entry=Read(fixture,1,true);Check(!ReferenceEquals(entry,Read(fixture,1)),"entrance and post caches separate");Eq(fixture,1,true);
  Patch(fixture,"{\"useSelectedEnemySlots\":false,\"attackPatterns\":[{\"selectedEnemySlots\":[0,2],\"attackSettings\":{\"attacksPerSecond\":3}},{\"selectedEnemySlots\":[1,2],\"attackSettings\":{\"attacksPerSecond\":9}}]}");for(int i=0;i<4;i++)Eq(fixture,i);Check(Read(fixture,2).AttacksPerSecond==3,"Multiple first matching pattern priority");
  Patch(fixture,"{\"attackPatterns\":[],\"executionMode\":1}");fixture.AttackSequence.steps.Clear();
  var a=new DirectedWaveAttackSequenceStep{overrideTargetSlots=true,targetSlots=new List<int>{1}};JsonUtility.FromJsonOverwrite("{\"attackSettings\":{\"attacksPerSecond\":4}}",a.pattern);
  var bstep=new DirectedWaveAttackSequenceStep();JsonUtility.FromJsonOverwrite("{\"attackSettings\":{\"attacksPerSecond\":6}}",bstep.pattern);fixture.AttackSequence.steps.Add(a);fixture.AttackSequence.steps.Add(bstep);fixture.InvalidateSequenceGuides();Eq(fixture,0);Eq(fixture,1);Check(Read(fixture,0).AttacksPerSecond==6&&Read(fixture,1).AttacksPerSecond==4,"Sequence guides remain slot-specific");
  Patch(fixture,"{\"executionMode\":0}");var preset=ScriptableObject.CreateInstance<DirectedWaveAttackPreset>();objects.Add(preset);var settings=new DirectedWaveAttackSettings();settings.SetAttacksPerSecond(11);preset.SetAttackSettings(settings);Set(fixture,"attackPreset",preset);var beforePreset=Read(fixture);settings.SetAttacksPerSecond(13);preset.SetAttackSettings(settings);var afterPreset=Read(fixture);Check(afterPreset.AttacksPerSecond==13&&!ReferenceEquals(beforePreset,afterPreset),"attack preset revision invalidates without owner edit");
  Set(fixture,"attackPreset",null);Set(fixture,"attackSettings.burstSettingsSource",1);
  var projectile=ScriptableObject.CreateInstance<EnemyProjectilePreset>();objects.Add(projectile);var shooting=new EnemyShootingSettings();JsonUtility.FromJsonOverwrite("{\"overrideBaseSize\":true,\"baseSize\":2}",shooting);projectile.SetSettings(shooting);Set(fixture,"attackSettings.waveBurstSettings.shooting.projectilePreset",projectile);var beforeProjectile=Read(fixture);Check(beforeProjectile.WaveBurstSettings.Shooting.BaseSize==2,"linked projectile preset read");JsonUtility.FromJsonOverwrite("{\"baseSize\":3}",shooting);projectile.SetSettings(shooting);var afterProjectile=Read(fixture);Check(afterProjectile.WaveBurstSettings.Shooting.BaseSize==3&&!ReferenceEquals(beforeProjectile,afterProjectile),"projectile preset revision invalidates");
  Set(fixture,"attackSettings.waveBurstSettings.shooting.projectilePreset",null);var authored=(DirectedWaveAttackSettings)typeof(DirectedWaveAttackBehaviour).GetField("attackSettings",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(fixture);var child=new EnemyChildAttackSettings();JsonUtility.FromJsonOverwrite("{\"triggerValue\":2}",child);authored.WaveBurstSettings.AuthoredShooting.SetChildAttack(child);EditorUtility.SetDirty(fixture);var beforeChild=Read(fixture);Check(beforeChild.WaveBurstSettings.Shooting.ChildAttack.TriggerValue==2,"child first value");JsonUtility.FromJsonOverwrite("{\"triggerValue\":5}",child);EditorUtility.SetDirty(fixture);Check(Read(fixture).WaveBurstSettings.Shooting.ChildAttack.TriggerValue==5,"nested Child edit invalidates by owner dirty count");
  var local=root.AddComponent<DirectedWaveEnemyOverride>();var localProfile=new EnemyBurstAttackSettings();localProfile.ConfigureLegacySingleAttack(3,1,.2f);local.SetAttackSettingsOverride(localProfile);var cached=Read(fixture);var fresh=new DirectedWaveAttackSettings();fixture.TryCopyResolvedAttackSettingsTo(0,false,fresh);Check(JsonUtility.ToJson(EnemyAttackSettingsResolver.CreateRuntimeCopy(cached.WaveBurstSettings,local,null))==JsonUtility.ToJson(EnemyAttackSettingsResolver.CreateRuntimeCopy(fresh.WaveBurstSettings,local,null)),"Local Overrides preserve resolver result");localProfile.ConfigureLegacySingleAttack(7,1,.2f);local.SetAttackSettingsOverride(localProfile);Check(EnemyAttackSettingsResolver.CreateRuntimeCopy(Read(fixture).WaveBurstSettings,local,null).AttackShotCount==7,"Local Override edit not frozen in shared cache");
  var result=new{success=true,checks=checks.ToArray()};string json=(string)Assembly.Load("Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new object[]{result});File.WriteAllText("AgentArtifacts/SceneAttackCache-regression.json",json);return new{success=true,checks=checks.Count};
 }finally{if(undoGroup>=0)Undo.RevertAllDownToGroup(undoGroup);foreach(var o in objects)if(o!=null)Object.DestroyImmediate(o);if(fixtureRoot!=null)PrefabUtility.UnloadPrefabContents(fixtureRoot);Clear();}
 }
}

